select pg_temp.check_true((select refund_status='pending' and revision>current_setting('qa.managed.pre_refund_revision')::bigint and refunded_amount_minor=0 from public.managed_checkout_orders where attempt_id='ac570000-0000-4000-8000-000000000060'),'pending refund is a durable revision without revoking payment');
