select pg_temp.check_true((public.begin_managed_checkout_operation(current_setting('qa.managed.scope')::jsonb,'ac570000-0000-4000-8000-000000000050',current_setting('qa.managed.refund_request')::jsonb||'{"attempt_id":"ac570000-0000-4000-8000-000000000050","request_id":"ac570000-0000-4000-8000-000000000071"}')->>'amount_minor')::bigint=15900,'refund remaining freezes actual balance while request asserts original total');
